window.VT = { D: VTDomain, state: VTStorage.load(), route: {}, forms: {}, views: {}, toastTimer: null };
window.VTUI = (() => {
  const V = VT;
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const date = value => value ? new Intl.DateTimeFormat('id-ID',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Jakarta'}).format(new Date(value.length === 10 ? value+'T12:00:00+07:00' : value)) : '—';
  const clock = value => value ? new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'}).format(new Date(value)) : '—';
  const roles = {PM:'Project Manager',LEADER:'Ketua tim',MEMBER:'Anggota tim',FINANCE:'Finance & Accounting',HR:'Pengelola SDM',ASSET:'Pengelola aset',OPS:'Operational Manager'};
  const states = {DRAFT:'Draft',PUBLISHED:'SK terbit',ACCEPTED:'Diterima',APPEALED:'Banding',IN_PROGRESS:'Berjalan',COMPLETION_REVIEW:'Review penyelesaian',COMPLETED:'Selesai',CANCELLED:'Dibatalkan',SUBMITTED:'Menunggu review',APPROVED:'Disetujui',CHANGES_REQUESTED:'Perlu perbaikan',PENDING_PM:'Menunggu PM',AWAITING_LEADER_ACCEPTANCE:'Menunggu ketua',AWAITING_ACCEPTANCE:'Menunggu penerimaan',EFFECTIVE:'Efektif',REJECTED:'Ditolak',SUPERSEDED:'Versi sebelumnya',ACTIVE:'Aktif',INACTIVE:'Nonaktif',VERIFIED:'Terverifikasi',PENDING:'Menunggu verifikasi',CURRENT:'Berlaku',NEEDS_REVIEW:'Perlu review',AUTO_VALID:'Valid otomatis',IN_USE:'Dipakai',RESERVED:'Direservasi',AVAILABLE:'Tersedia',RETURN_PENDING:'Menunggu pemeriksaan',OPEN:'Terbuka',RESOLVED:'Selesai',WITHDRAWN:'Ditarik PM'};
  const badge = status => `<span class="badge ${['COMPLETED','APPROVED','ACCEPTED','EFFECTIVE','ACTIVE','VERIFIED','CURRENT','AVAILABLE','AUTO_VALID','RESOLVED'].includes(status)?'green':['REJECTED','CANCELLED','INACTIVE'].includes(status)?'red':['IN_PROGRESS','PUBLISHED','IN_USE'].includes(status)?'blue':['DRAFT','SUPERSEDED'].includes(status)?'':'amber'}">${esc(states[status] || status)}</span>`;
  const unit = code => V.D.units.find(u => u.code === code)?.name || code || 'Lintas unit';
  const person = id => V.state.employees.find(e => e.id === id)?.name || V.D.actors.find(a => a.id === id)?.name || id || '—';
  const initials = name => String(name).split(' ').slice(0,2).map(s=>s[0]).join('');
  const avatar = (name,large=false) => `<span class="avatar ${large?'large':''}">${esc(initials(name))}</span>`;
  const href = (...parts) => '#/' + [V.route.device,V.actor.id,...parts].map(encodeURIComponent).join('/');
  const link = (path,label,kind='') => `<a class="btn ${kind}" href="${href(...path)}">${esc(label)}</a>`;
  const button = (ui,label,payload={},kind='') => `<button type="button" class="btn ${kind}" data-ui="${esc(ui)}" data-payload="${esc(JSON.stringify(payload))}">${esc(label)}</button>`;
  const command = (action,label,payload={},kind='',guard=false) => {
    const reason = guard ? V.D.transition(V.state,V.actor,action,payload).error : '';
    return `<button type="button" class="btn ${kind}" data-command="${action}" data-payload="${esc(JSON.stringify(payload))}"${guard?' data-guard="true"':''}${reason?` disabled title="${esc(reason)}"`:''}>${esc(label)}</button>${reason?`<small class="action-reason">${esc(reason)}</small>`:''}`;
  };
  const actions = (...items) => `<div class="actions">${items.join('')}</div>`;
  const note = (text,kind='') => `<div class="note ${kind}">${esc(text)}</div>`;
  const panel = (title,body) => `<section class="panel"><h2>${esc(title)}</h2>${body}</section>`;
  const heading = (title,description='',cta='',eyebrow='VISIONTECH WORKSPACE') => `<header class="page-intro"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${cta?actions(cta):''}</header>`;
  const dl = rows => `<dl class="detail-list">${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
  const table = (heads,rows) => `<div class="table-wrap" role="region" aria-label="${esc(heads[0])}" tabindex="0"><table><thead><tr>${heads.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const empty = (title,desc='Belum ada data pada bagian ini.',cta='') => `<div class="panel empty"><h2>${esc(title)}</h2><p>${esc(desc)}</p>${cta}</div>`;
  const row = (name,desc,cta='',initial='') => `<div class="row">${initial?avatar(initial):''}<div><strong>${esc(name)}</strong><small>${esc(desc)}</small></div>${cta}</div>`;
  const input = (name,label,value='',type='text',extra='') => `<label>${esc(label)}<input name="${esc(name)}" aria-label="${esc(label)}" type="${type}" value="${esc(value)}" ${extra}></label>`;
  const textarea = (name,label,value='',extra='') => `<label>${esc(label)}<textarea name="${esc(name)}" aria-label="${esc(label)}" ${extra}>${esc(value)}</textarea></label>`;
  const select = (name,label,options,value,extra='') => `<label>${esc(label)}<select name="${esc(name)}" aria-label="${esc(label)}" ${extra}>${options.map(([id,text])=>`<option value="${esc(id)}"${String(value)===String(id)?' selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
  const hidden = (name,value) => `<input type="hidden" name="${name}" value="${esc(value)}">`;
  const form = (name,body,submit='Simpan',payload={}) => `<form data-form="${name}">${Object.entries(payload).map(([k,v])=>hidden(k,v)).join('')}${body}${submit ? `<div class="form-footer"><button class="btn primary" type="submit">${esc(submit)}</button></div>` : ''}</form>`;
  const attachment = (file,extra='') => `<div class="attachment"><span>${esc(typeof file==='string'?file:file.name)}</span>${typeof file==='string'?'<small>Berkas contoh tidak tersedia</small>':button('attachment','Pratinjau',file,'small')}${extra}</div>`;
  const upload = (label='Lampiran',name='files',multiple=true) => `<label>${esc(label)}<input type="file" name="${name}" aria-label="${esc(label)}" ${multiple?'multiple':''}></label><p class="field-hint">Maksimal 10 MB per berkas. Gambar/PDF dapat dipratinjau; format lain dapat diunduh.</p>`;
  const icons = {home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',plans:'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4',approvals:'M3 5h18v14H3z M3 12h5l2 3h4l2-3h5',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-3a4 4 0 0 0-3-3.8',organization:'M8 2h8v6H8z M2 16h6v6H2z M16 16h6v6h-6z M12 8v4 M5 16v-4h14v4',attendance:'M12 3a9 9 0 1 0 9 9 M12 7v5l4 2',assets:'M3 7h18v14H3z M8 7V3h8v4 M3 12h18 M10 12v3h4v-3',audit:'M4 4v5h5 M4 9a8 8 0 1 1 0 7 M12 7v5l3 2',profile:'M20 21v-2a7 7 0 0 0-14 0v2 M13 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',more:'M5 12h.01 M12 12h.01 M19 12h.01',documents:'M6 3h8l5 5v13H6z M14 3v6h5 M9 13h6 M9 17h6',timeline:'M4 5h16v16H4z M8 2v6 M16 2v6 M4 10h16'};
  const icon = name => `<svg class="nav-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${icons[name]||icons.plans}"/></svg>`;
  return {esc,date,clock,roles,states,badge,unit,person,avatar,href,link,button,command,actions,note,panel,heading,dl,table,empty,row,input,textarea,select,hidden,form,attachment,upload,icon};
})();
